import numpy as np
def equation(eps, T, params):
    a,b,c,d,f,g,h,m,k1,k2 = params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9]
    G1 = np.exp(-k1*np.sqrt(T))
    G2 = np.exp(-k2*np.sqrt(T))
    return -(a + b*eps + c*T + d*eps*T + f*T**2 + g*G1 + h*T*G1 + m*eps*G2)
